import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
items=[('welding', 1, 'SMAW – Corner Joint', 'Understand the two faces and seam of a corner joint.', 'Recognise the geometry of a shielded metal arc welded corner joint. The drawing is a conceptual view, without welding parameters.', ['Identify the two plate faces and their meeting edge.', 'Locate the highlighted seam and sketch the corner geometry.', 'Label the joint in your own drawing. Obtain actual welding settings and practice instructions from your instructor.'], [('What does SMAW stand for?', 'Shielded Metal Arc Welding.'), ('What does the highlighted line identify?', 'The meeting edge where the two plates are joined; it does not specify a weld size or operating setting.')]), ('welding', 2, 'Staircase Welding and Lighting Assembly', 'Connect a staircase model with a simple low-voltage lighting concept.', 'Identify the structural steps, lighting positions and separate low-voltage circuit in a staircase assembly.', ['Identify the base, stair profile and marked lighting positions.', 'Follow the separate battery, switch and light circuit shown in the lower schematic.', 'Sketch the mechanical and electrical views separately. Ask your faculty which diagrams are required.'], [('Why show the lighting circuit separately?', 'It makes the electrical connections easier to distinguish from the staircase structure.'), ('Is the circuit a mains-wiring diagram?', 'No. It is a conceptual battery-powered light circuit and does not specify a rated practical installation.')]), ('welding', 3, 'Solar Based Power Generation System', 'Follow the flow of energy from a solar panel to a load.', 'Identify a solar panel, controller, storage battery and load in a conceptual energy system.', ['Follow the connections from panel to controller, battery and load.', 'Explain where sunlight is converted into electrical energy and where energy is stored.', 'Redraw the block arrangement and label each component. Use only instructor-approved hardware and wiring instructions for a practical model.'], [('What is the role of the panel?', 'It converts incident light into electrical energy.'), ('What is the role of the battery in this example?', 'It stores energy for later use. The diagram does not specify battery chemistry, charging settings or component ratings.')]), ('carpentry', 1, 'Cross Halving Joint', 'See how two recessed wooden members overlap.', 'Understand how complementary recesses permit two wooden strips to cross.', ['Locate the overlap region on both wooden members.', 'Use the separated view to see the matching recesses.', 'Sketch the joint and label each member. Take working dimensions and cutting instructions from your faculty.'], [('Why show an exploded view?', 'It exposes the recesses that become hidden when the members overlap.'), ('Does the sketch specify the notch depth?', 'No. A dimensioned drawing is needed before constructing a physical joint.')]), ('carpentry', 2, 'Wooden Robot Fabrication', 'Identify the head, body, limbs and joints of a wooden model.', 'Distinguish the major wooden components and the pivot joints in a robot-shaped model.', ['Identify the body, head, two arms and two legs in the model.', 'Mark the circular joints and distinguish them from the wooden members.', 'Sketch the model and label its components. Confirm the required construction details with your faculty.'], [('What do the circles represent?', 'Simplified pivot connections between the model’s components.'), ('Does the model need to be powered?', 'A wooden model can be static or articulated. The actual experiment requirements depend on the faculty-approved design.')]), ('carpentry', 3, 'Motorized Robotic Arm Activation', 'Explore the links, pivot and motor in a simplified robotic arm.', 'Identify the motor-driven pivot, arm links and end attachment of a simplified robotic arm.', ['Identify the base, motor, lower arm, upper arm and end attachment.', 'Follow the arm from the driven pivot to the end attachment.', 'Explain how turning one joint changes the arm pose. Treat the picture as a component diagram, not a circuit or control program.'], [('What is the motor’s role?', 'To provide rotational motion at a driven joint through a suitable connection.'), ('Is a motor alone a complete arm control system?', 'No. Power, mechanical coupling, control and suitable limits depend on the actual implementation.')]), ('sheet-metal', 1, 'Rectangular Tray Making', 'Relate a flat sheet layout to an open rectangular tray.', 'Identify the base, four walls and fold lines of a conceptual rectangular tray.', ['Locate the central base and four surrounding flaps in the flat view.', 'Match the dashed fold lines with the walls in the formed tray.', 'Sketch both views. Real sheet-metal dimensions require thickness and bend information from your instructor.'], [('Which region becomes the tray base?', 'The central rectangle in the unfolded layout.'), ('Why can’t this flat net be used as a cutting template?', 'It has no dimensions, material thickness, bend allowance or joining details.')]), ('sheet-metal', 2, 'Mini Motorized Forklift Fabrication', 'Identify the separate components of a small forklift model.', 'Study the chassis, wheels, mast and fork carriage before assembly.', ['Identify the separate chassis, wheels, mast and carriage in the component view.', 'Compare their relative positions before joining them in a sketch.', 'Prepare a labelled component list. Actual fabrication dimensions, fasteners and motor mounting must come from your approved drawing.'], [('What is the mast?', 'The upright structure associated with guiding the lifting carriage.'), ('Why use a separated component view?', 'It helps identify the parts and their relationships before studying the complete assembly.')]), ('sheet-metal', 3, 'Mini Motorized Forklift', 'Explore the assembled forklift and the path of its moving carriage.', 'Identify how the carriage is guided by the mast in the assembled model.', ['Identify the wheels, mast, fork carriage and lifting direction on the assembled model.', 'Separate the idea of vehicle movement from the vertical motion of the carriage.', 'Draw the assembly and label the visible components. Confirm the motor and lift mechanism used in your actual model with your faculty.'], [('What supports the item being lifted?', 'The forks attached to the carriage in this conceptual model.'), ('Does this sketch establish a safe load?', 'No. Load capacity depends on the actual design, materials, stability and testing.')]), ('fitting', 1, 'Step Fitting', 'Compare the complementary profiles of two stepped pieces.', 'Identify a stepped projection and its complementary recess.', ['Trace the stepped profile on each of the two pieces.', 'Compare the projection with the matching opening without assuming a physical fit.', 'Sketch both profiles. A real fit must be checked against measured dimensions and specified clearances.'], [('What makes the profiles complementary?', 'The stepped projection on one piece corresponds to the recess on the other.'), ('Does a matching sketch guarantee a fit?', 'No. Actual dimensions, tolerances and inspection determine whether real parts fit.')]), ('fitting', 2, 'Scissor Lift Mechanism Fabrication and Assembly', 'Identify crossed links, pivots and the lift platform.', 'Explain how crossed links and pivot connections form a scissor lift arrangement.', ['Identify the crossed links and their centre pivot.', 'Locate the platform, base and end joints or sliding connections.', 'Sketch the arrangement and explain its changing height. Actual travel and load limits require a dimensioned, supervised design.'], [('What connects the two crossed links?', 'A pivot at their crossing point in the simplified drawing.'), ('Does the diagram establish safe lifting capacity?', 'No. It illustrates component relationships, not structural capacity or certified operation.')]), ('fitting', 3, 'Fabrication and Assembly of a DC Motor-Driven Pulley Mechanism for Energy Conversion', 'Follow electrical and mechanical energy through a belt-and-pulley arrangement.', 'Identify a driving motor, belt, driven pulley and generator in a conceptual energy-conversion arrangement.', ['Locate the driving DC motor, belt and driven shaft in the schematic.', 'Follow the energy path: supply to motor, rotating belt transmission, then generator and load.', 'Sketch and label the assembly. The layout is illustrative; motor ratings, pulley sizes, tension and wiring must follow your instructor’s specifications.'], [('What does the belt transmit?', 'Mechanical rotation between the driving and driven pulley shafts.'), ('Is the final electrical output equal to the electrical input?', 'No. Motor, transmission and generator losses mean the arrangement is not a source of free energy.')])]
